begin;
create temporary table tracker_test_state as select o.user_id as owner,o.participant_id as existing_pid,(select a.user_id from public.participant_access a where a.participant_id=o.participant_id and a.user_id<>o.user_id and a.can_write limit 1) as colleague,null::uuid as pid,null::uuid as period,null::uuid as day from private.tracker_owners o limit 1;
grant select,update on tracker_test_state to authenticated;
select set_config('request.jwt.claims',json_build_object('sub',owner,'role','authenticated')::text,true) from tracker_test_state;
set local role authenticated;
do $$ declare s record; new_pid uuid; new_period uuid; begin
 select * into s from tracker_test_state;
 new_pid:=public.tracker_create_client('Rollback-only test tracker');
 update tracker_test_state set pid=new_pid;
 new_period:=public.tracker_save_period(new_pid,'Test period','2026-11-02','2026-11-06',array['end_of_day'],array[1,2,3,4,5],true,array['2026-11-04'::date]);
 update tracker_test_state set period=new_period;
 begin perform public.tracker_save_period(new_pid,'Overlap','2026-11-03','2026-11-10',array['end_of_day'],array[1],true); raise exception 'Overlap accepted' using errcode='ZX001'; exception when sqlstate 'P0001' then null; end;
 if jsonb_array_length(public.tracker_admin_data(new_pid,'2026-11-02','2026-11-06')->'periods')<>1 then raise exception 'Period missing'; end if;
end $$;
reset role;
insert into public.participant_access(participant_id,user_id,access_role,can_view,can_write) select pid,colleague,'school',true,true from tracker_test_state;
select set_config('request.jwt.claims',json_build_object('sub',colleague,'role','authenticated')::text,true) from tracker_test_state;
set local role authenticated;
do $$ declare s record; new_day uuid; begin
 select * into s from tracker_test_state;
 if jsonb_array_length(public.tracker_schedule(s.pid))<>1 then raise exception 'Assigned member cannot read schedule'; end if;
 begin perform public.tracker_admin_data(s.pid,'2026-11-02','2026-11-06'); raise exception 'Member read admin data'; exception when insufficient_privilege then null; end;
 begin perform public.tracker_create_client('Unauthorised'); raise exception 'Member created client'; exception when insufficient_privilege then null; end;
 begin perform public.tracker_save_period(s.pid,'No permission','2026-12-01','2026-12-02',array['end_of_day'],array[1],true); raise exception 'Member configured period'; exception when insufficient_privilege then null; end;
 begin perform count(*) from private.tracker_save_history; raise exception 'Member read private audit'; exception when insufficient_privilege then null; end;
 insert into public.tracker_days(participant_id,tracking_date,sleep,breakfast,home_morning,medication_status) values(s.pid,'2026-11-02','Slept through','Ate well','Usual','Usual') returning id into new_day;
 update tracker_test_state set day=new_day;
 insert into public.school_checkpoints(tracker_day_id,checkpoint,participation,regulation) values(new_day,'end_of_day','independent','settled');
 update public.school_checkpoints set regulation='some_difficulty' where tracker_day_id=new_day;
 begin insert into public.school_checkpoints(tracker_day_id,checkpoint,participation) values(new_day,'mid_morning','independent'); raise exception 'Unscheduled checkpoint accepted' using errcode='ZX001'; exception when sqlstate 'P0001' then null; end;
 begin insert into public.tracker_days(participant_id,tracking_date) values(s.pid,'2026-11-04'); raise exception 'Excluded day accepted' using errcode='ZX001'; exception when sqlstate 'P0001' then null; end;
 begin insert into public.tracker_days(participant_id,tracking_date) values(s.pid,'2026-11-09'); raise exception 'Paused date accepted' using errcode='ZX001'; exception when sqlstate 'P0001' then null; end;
end $$;
reset role;
do $$ declare s record; begin select * into s from tracker_test_state;
 if (select count(*) from private.tracker_save_history where participant_id=s.pid)<>3 then raise exception 'Expected home save plus two checkpoint versions'; end if;
 if exists(select 1 from private.tracker_save_history where participant_id=s.pid and actor_id is distinct from s.colleague) then raise exception 'Incorrect audit actor'; end if;
end $$;
select set_config('request.jwt.claims',json_build_object('sub',owner,'role','authenticated')::text,true) from tracker_test_state;
set local role authenticated;
do $$ declare s record; d jsonb; begin select * into s from tracker_test_state;d:=public.tracker_admin_data(s.pid,'2026-11-02','2026-11-06');if jsonb_array_length(d->'history')<>3 or jsonb_array_length(d->'days')<>1 then raise exception 'Dashboard data missing'; end if;end $$;
reset role;
rollback;
